-- Chemistry GCE A/L 2017 curriculum hierarchy based on the official NIE syllabus.
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),s as(select id from public.subjects where name='Chemistry'),x(code,title,position) as(values ('1.0','Atomic Structure',1),('2.0','Structure and Bonding',2),('3.0','Chemical Calculations',3),('4.0','Gaseous State of Matter',4),('5.0','Energetics',5),('6.0','Chemistry of s, p and d Block Elements',6),('7.0','Basic Concepts of Organic Chemistry',7),('8.0','Hydrocarbons and Halohydrocarbons',8),('9.0','Oxygen Containing Organic Compounds',9),('10.0','Nitrogen Containing Organic Compounds',10),('11.0','Chemical Kinetics',11),('12.0','Equilibrium',12),('13.0','Electrochemistry',13),('14.0','Industrial Chemistry and Environmental Pollution',14))
insert into public.syllabus_competencies(syllabus_version_id,subject_id,code,title,description,position)
select v.id,s.id,x.code,x.title,'NIE GCE A/L Chemistry 2017 Unit '||x.position||' competency.',x.position from v cross join s cross join x
where not exists(select 1 from public.syllabus_competencies z where z.syllabus_version_id=v.id and z.subject_id=s.id and z.code=x.code);
