n',1),('7.2.1','7.0','Nomenclature',2),('7.3.1','7.0','Isomerism',3),('7.4.1','7.0','Bonding and hybridization in organic compounds',4),('7.5.1','7.0','Organic reaction mechanisms',5),('7.6.1','7.0','Purification and analysis of organic compounds',6),('8.1.1','8.0','Alkanes',1),('8.2.1','8.0','Alkenes',2),('8.3.1','8.0','Alkynes',3),('8.4.1','8.0','Aromatic hydrocarbons',4),('8.5.1','8.0','Halogenoalkanes and halogenoarenes',5),('8.6.1','8.0','Preparation and reactions of hydrocarbons',6),('9.1.1','9.0','Alcohols',1),('9.2.1','9.0','Phenols',2),('9.3.1','9.0','Ethers',3),('9.4.1','9.0','Aldehydes',4),('9.5.1','9.0','Ketones',5),('9.6.1','9.0','Carboxylic acids',6),('9.7.1','9.0','Esters and related reactions',7),('10.1.1','10.0','Amines',1),('10.2.1','10.0','Amides',2),('10.3.1','10.0','Amino compounds and basicity',3),('10.4.1','10.0','Diazonium compounds',4),('10.5.1','10.0','Selected nitrogen-containing organic reactions',5),('11.1.1','11.0','Rate of reaction',1),('11.2.1','11.0','Factors affecting reaction rate',2),('11.3.1','11.0','Rate laws',3),('11.4.1','11.0','Order of reaction',4),('11.5.1','11.0','Activation energy',5),('11.6.1','11.0','Arrhenius equation',6),('11.7.1','11.0','Catalysis',7),('12.1.1','12.0','Dynamic equilibrium',1),('12.2.1','12.0','Equilibrium constant',2),('12.3.1','12.0','Le Chatelier principle',3),('12.4.1','12.0','Acid-base equilibrium',4),('12.5.1','12.0','pH and pOH',5),('12.6.1','12.0','Buffer solutions',6),('12.7.1','12.0','Solubility equilibrium',7),('12.8.1','12.0','Common ion effect',8),('13.1.1','13.0','Redox reactions',1),('13.2.1','13.0','Electrochemical cells',2),('13.3.1','13.0','Cell potentials',3),('13.4.1','13.0','Nernst equation',4),('13.5.1','13.0','Electrolysis',5),('13.6.1','13.0','Faraday laws',6),('13.7.1','13.0','Applications of electrochemistry',7),('14.1.1','14.0','Industrial chemical processes',1),('14.2.1','14.0','Fertilizer industry',2),('14.3.1','14.0','Cement and related industries',3),('14.4.1','14.0','Pe