insert into public.syllabus_competency_levels(competency_id,syllabus_version_id,subject_id,code,title,description,position)
select c.id,v.id,s.id,x.code,x.title,'Curriculum learning area from the official NIE Chemistry 2017 syllabus.',x.position
from v cross join s cross join x join public.syllabus_competencies c on c.syllabus_version_id=v.id and c.subject_id=s.id and c.code=x.cc
where not exists(select 1 from public.syllabus_competency_levels z where z.syllabus_version_id=v.id and z.subject_id=s.id and z.code=x.code);
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),s as(select id from public.subjects where name='Chemistry'),cl as(select * from public.syllabus_competency_levels where syllabus_version_id=(select id from v) and subject_id=(select id from s))
insert into public.syllabus_subtopics(topic_id,title,description,position)
select t.id,'Core learning outcomes','NIE GCE A/L Chemistry 2017 curriculum learning area.',1
from cl join public.syllabus_topics t on t.title=cl.title join public.syllabus_units u on u.id=t.unit_id and u.position=split_part(cl.code,'.',1)::int and u.subject_id=cl.subject_id and u.syllabus_version_id=cl.syllabus_version_id
where not exists(select 1 from public.syllabus_subtopics z where z.topic_id=t.id and z.title='Core learning outcomes');
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),s as(select id from public.subjects where name='Chemistry'),cl as(select * from public.syllabus_competency_levels where syllabus_version_id=(select id from v) and subject_id=(select id from s))
insert into public.syllabus_learning_outcomes(subtopic_id,competency_id,competency_level_id,code,statement,position)
select st.id,cl.competency_id,cl.id,cl.code,cl.title,1
from cl join public.syllabus_topics t on t.title=cl.title join public.syllabus_units u on u.id=t.unit_id and u.position=split_part(cl.code,'.',1)::int and u.subject_id=cl.subject_id and u.syllabus_version_id=cl.syllabus_version_id
join public.syllabus_subtopics st on st.topic_id=t.id and st.title='Core learning outcomes'
where not exists(select 1 from public.syllabus_learning_outcomes z where z.subtopic_id=st.id and z.code=cl.code);
